package com.townyreborn.staffconnector;
import java.util.*;import java.util.concurrent.*;import java.util.function.*;import java.time.*;import java.net.*;import java.net.http.*;import java.nio.file.*;
/** Public release notifications, never installs or downloads executables. */
final class PluginUpdates implements AutoCloseable {
 private final Path dir;private final Consumer<Map<String,Object>> sink;private final Supplier<List<Map<String,Object>>> inventory;private final Supplier<String> version;private final String loader;private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).followRedirects(HttpClient.Redirect.NEVER).build();private final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"TR-PluginUpdates");t.setDaemon(true);return t;});private volatile boolean running;
 PluginUpdates(Path dir,Consumer<Map<String,Object>> sink,Supplier<List<Map<String,Object>>> inventory,Supplier<String> version,String loader){this.dir=dir;this.sink=sink;this.inventory=inventory;this.version=version;this.loader=loader;}
 void start(){try{Path file=dir.resolve("update-sources.properties");if(!Files.exists(file))try(var in=getClass().getResourceAsStream("/update-sources.properties")){if(in!=null)Files.copy(in,file);}Path cache=dir.resolve("plugin-updates-cache.json");if(Files.exists(cache)&&Json.decode(Files.readString(cache)) instanceof Map<?,?> data&&data.get("plugins") instanceof List<?> rows){for(int i=0;i<rows.size();i+=15)sink.accept(Map.of("type","plugin.updates","plugins",rows.subList(i,Math.min(rows.size(),i+15))));}}catch(Exception ignored){}worker.scheduleWithFixedDelay(this::check,30,21600,TimeUnit.SECONDS);}
 void requestCheck(){if(!running)worker.execute(this::check);}
 private void check(){if(running)return;running=true;try{Properties sources=new Properties();Path file=dir.resolve("update-sources.properties");if(Files.exists(file))try(var stream=Files.newInputStream(file)){sources.load(stream);}List<Map<String,Object>> results=new ArrayList<>(),batch=new ArrayList<>();for(Map<String,Object> plugin:inventory.get()){if(Thread.currentThread().isInterrupted())break;String name=t(plugin.get("name")),installed=t(plugin.get("version")),source=sources.getProperty(name,sourceFromWebsite(t(plugin.get("website"))));Map<String,Object> row=new LinkedHashMap<>();row.put("name",name);row.put("installed_version",installed);row.put("source",source);row.put("checked_at",Instant.now().toString());row.put("next_check_at",Instant.now().plusSeconds(21600).toString());row.put("state","unknown");if(name.startsWith("TownyReborn")||installed.toLowerCase(Locale.ROOT).matches(".*(townyreborn|hzcgc|3uses|localstorage|villagerplacement).*")){row.put("state","custom");row.put("reason","Custom server build; review its own source before updating.");}else if(source.isBlank()||source.equals("none")){row.put("reason","No verified public source configured.");}else try{String latest="",url="",compat="Minecraft and dependency compatibility must be checked before installing.";if(source.matches("spiget:[0-9]+")){Object result=get("https://api.spiget.org/v2/resources/"+source.substring(7)+"/versions/latest");if(result instanceof Map<?,?> m)latest=t(m.get("name"));url="https://www.spigotmc.org/resources/"+source.substring(7)+"/";}else if(source.matches("github:[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+")){Object result=get("https://api.github.com/repos/"+source.substring(7)+"/releases/latest");if(result instanceof Map<?,?> m){latest=t(m.get("tag_name"));url=t(m.get("html_url"));}}else if(source.matches("modrinth:[A-Za-z0-9_-]+")){Object result=get("https://api.modrinth.com/v2/project/"+source.substring(9)+"/version");Map<?,?> newest=null,compatible=null;if(result instanceof List<?> list)for(Object entry:list)if(entry instanceof Map<?,?> m&&"release".equals(m.get("version_type"))){if(m.get("loaders") instanceof List<?> ls&&!ls.contains(loader)&&!(loader.equals("paper")&&(ls.contains("bukkit")||ls.contains("spigot"))))continue;if(newest==null)newest=m;if(compatible==null&&m.get("game_versions") instanceof List<?> games&&games.contains(version.get()))compatible=m;}Map<?,?> chosen=compatible==null?newest:compatible;if(chosen!=null){latest=t(chosen.get("version_number"));url="https://modrinth.com/plugin/"+source.substring(9)+"/version/"+t(chosen.get("id"));}compat=compatible==null?"No stable release listed for "+version.get()+" / "+loader:"Listed for "+version.get()+" / "+loader;row.put("compatibility_warning",compatible==null);}else throw new IllegalArgumentException("Unsupported public source.");if(latest.isBlank())throw new IllegalStateException("No stable public release returned.");row.put("latest_version",latest);row.put("url",url);row.put("compatibility",compat);Integer diff=compareVersions(latest,installed);row.put("state",diff==null?"unverified":diff>0?"update_available":diff<0?"newer_build":"current");if(diff==null)row.put("reason","Version labels cannot be compared safely.");}catch(Exception error){row.put("state","check_failed");row.put("reason",TelemetryBuffer.clean(error.getMessage(),180));}results.add(row);batch.add(row);if(batch.size()==15){sink.accept(Map.of("type","plugin.updates","plugins",List.copyOf(batch)));batch.clear();}}if(!batch.isEmpty())sink.accept(Map.of("type","plugin.updates","plugins",List.copyOf(batch)));Path tmp=dir.resolve("plugin-updates-cache.json.tmp"),out=dir.resolve("plugin-updates-cache.json");Files.writeString(tmp,Json.encode(Map.of("plugins",results)));try{Files.move(tmp,out,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,out,StandardCopyOption.REPLACE_EXISTING);}}catch(Exception ignored){}finally{running=false;}}
 private Object get(String url)throws Exception{HttpResponse<String> response=http.send(HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(8)).header("User-Agent","TownyRebornStaffHQ/4.0 (+https://staff.townyreborn.com)").header("Accept","application/json").GET().build(),HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200)throw new IllegalStateException("Provider HTTP "+response.statusCode());if(response.body().length()>4000000)throw new IllegalStateException("Provider response too large");return Json.decode(response.body());}
 static String sourceFromWebsite(String url){try{URI u=URI.create(url);String h=t(u.getHost()),p=t(u.getPath());java.util.regex.Matcher m;if(h.equals("spigotmc.org")||h.equals("www.spigotmc.org")){m=java.util.regex.Pattern.compile("/resources/(?:[^/]*\\.)?([0-9]+)(?:/|$)").matcher(p);if(m.find())return "spiget:"+m.group(1);}if(h.equals("modrinth.com")){m=java.util.regex.Pattern.compile("/(?:plugin|project|mod)/([A-Za-z0-9_-]+)").matcher(p);if(m.find())return "modrinth:"+m.group(1);}if(h.equals("github.com")&&p.matches("/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+/?"))return "github:"+p.replaceAll("^/|/$","");}catch(RuntimeException ignored){}return "";}
 static Integer compareVersions(String a,String b){var pattern=java.util.regex.Pattern.compile("(?i)^v?([0-9]+(?:\\.[0-9]+){1,5})([-+ ].*)?$");var x=pattern.matcher(a.trim());var y=pattern.matcher(b.trim());if(!x.matches()||!y.matches())return null;try{String[] xs=x.group(1).split("\\."),ys=y.group(1).split("\\.");for(int i=0;i<Math.max(xs.length,ys.length);i++){long left=i<xs.length?Long.parseLong(xs[i]):0,right=i<ys.length?Long.parseLong(ys[i]):0;if(left!=right)return Long.compare(left,right);}String sx=t(x.group(2)).toLowerCase(Locale.ROOT),sy=t(y.group(2)).toLowerCase(Locale.ROOT);if(sx.equals(sy))return 0;if(sx.isEmpty()&&sy.matches(".*(snapshot|rc|alpha|beta).*"))return 1;if(sy.isEmpty()&&sx.matches(".*(snapshot|rc|alpha|beta).*"))return -1;return null;}catch(NumberFormatException e){return null;}}
 private static String t(Object v){return v==null?"":String.valueOf(v);}@Override public void close(){worker.shutdownNow();}
}
